import{_ as e,o as i,c as r,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-12-11:: Ceph DocUBetter Meeting","description":"","frontmatter":{"title":"2019-12-11:: Ceph DocUBetter Meeting","date":"2019-12-11T00:00:00.000Z","updated":"2019-12-12T00:00:00.000Z","tags":["Ceph","分布式存储","文档更新","软件集成","版本迁移"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-12-11_-_-_Ceph_DocUBetter_Meeting.md","filePath":"posts/2019/2019-12-11_-_-_Ceph_DocUBetter_Meeting.md","lastUpdated":1780460162000}'),l={name:"posts/2019/2019-12-11_-_-_Ceph_DocUBetter_Meeting.md"};function n(p,t,o,g,s,_){return i(),r("div",null,[...t[0]||(t[0]=[a("<p>本次Ceph DocUBetter会议于2019年12月11日凌晨3:30召开，与会人员包括Sage、Zack、Brad、Marc、Patrick、David、Florian、JT Layton和Brett等。会议主要讨论了以下议题：</p><ol><li><p><strong>硬件推荐文档</strong>：Marc创建的硬件推荐文档待审查，讨论了在文档中是否应明确提及测试的操作系统。</p></li><li><p><strong>模板更新</strong>：Brad修改了模板，试图恢复到原始的自然模板，讨论了颜色和样式的调整。</p></li><li><p><strong>Bug更新</strong>：Zack对etherpad中的bug进行了编号和修复，讨论了bug的进度和需要进一步审查的bug。</p></li><li><p><strong>硬件推荐PR</strong>：讨论了两个PR和一个关于硬件推荐的minor PR，决定在Marc的PR中整合所有想法。</p></li><li><p><strong>Landing Page和Getting Started Guide</strong>：计划在今年年底前完成Landing Page和Getting Started Guide的更新，讨论了需要添加的图片和结构调整。</p></li><li><p><strong>PG Repair Page</strong>：讨论了PG Repair Page的内容和需要与David沟通的事项。</p></li><li><p><strong>Python 3迁移</strong>：讨论了从Python 2迁移到Python 3的计划和潜在影响。</p></li><li><p><strong>旧业务回顾</strong>：讨论了之前的硬件推荐和操作系统测试的明确提及，讨论了文档bug的报告机制和简化流程。</p></li><li><p><strong>网络和Placement Groups问题</strong>：讨论了网络架构和Placement Groups的问题，计划安排会议进行深入讨论。</p></li><li><p><strong>文档更新和命名规范</strong>：讨论了文档更新和命名规范的更改，计划进行大规模的grep和replace操作。</p></li><li><p><strong>文档bug报告机制</strong>：讨论了简化文档bug报告机制，建议使用email list或etherpad。</p></li></ol><p>会议决定事项包括：</p><ul><li>硬件推荐文档需要审查和整合。</li><li>Landing Page和Getting Started Guide的更新计划在今年年底前完成。</li><li>简化文档bug报告机制，建议使用email list或etherpad。</li><li>安排会议讨论网络架构和Placement Groups问题。</li></ul><p>后续行动计划：</p><ul><li>Marc负责整合硬件推荐文档。</li><li>Zack负责更新Landing Page和Getting Started Guide。</li><li>安排会议讨论网络架构和Placement Groups问题。</li><li>简化文档bug报告机制，建议使用email list或etherpad。</li></ul><p>会议还讨论了网络连接问题和视频质量问题，以及Python 3迁移的潜在影响和需要进行的更改，以及文档更新和命名规范的更改。</p>",7)])])}const u=e(l,[["render",n]]);export{c as __pageData,u as default};
